script:
await step('Mở màn hình Cấu hình Đơn vị tạo phiếu Bảo trì', async () => {
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  assert(/\/maintenance\/config/.test(page.url()), 'Tài khoản không có quyền vào cấu hình Bảo trì');
});

await step('Kiểm tra các phần cấu hình Vị trí tạo phiếu, Đánh giá và Danh sách đơn vị', async () => {
  const txt = await page.locator('body').innerText();
  assert(txt.length > 50, 'Màn hình cấu hình đơn vị tạo phiếu trống');
  if (ctx.has('ten_don_vi')) {
    const keyword = ctx.val('ten_don_vi');
    ctx.log('Kiểm tra đơn vị: ' + keyword + ' -> ' + (txt.includes(keyword) ? 'Có trên trang' : 'Chưa thấy trên trang đầu'));
  }
});
